import Foundation

public enum PasteboardFilter {
    public static let ownMarkerType = "com.maicolsantos.clips.internal"

    public static let sensitiveTypes: Set<String> = [
        ownMarkerType,
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword"
    ]

    public static func shouldIgnore(types: [String]) -> Bool {
        for type in types {
            if sensitiveTypes.contains(type) {
                return true
            }
        }
        return false
    }
}
